from typing import List

class Solution:
    def firstMissingPositive(self, nums: List[int]) -> int:
        size = len(nums)

        # 第一步：原地哈希，将每个合法正整数 v 放到下标 v-1 的位置
        for i in range(size):
            # 持续交换，直到 nums[i] 到达正确位置，或目标位置已有正确的数
            while 1 <= nums[i] <= size and nums[i] != nums[nums[i] - 1]:
                j = nums[i] - 1
                nums[i], nums[j] = nums[j], nums[i]

        # 第二步：顺序扫描，找第一个"位置与值不匹配"的下标
        for i in range(size):
            if nums[i] != i + 1:
                return i + 1

        # 第三步：如果 1~n 全部存在，答案是 n+1
        return size + 1
